section('Papers kept with a compliance')
def upload(sess, profile, cid, name, data):
    bnd = 'x' + uid() + uid()
    body = b''.join([f'--{bnd}\r\nContent-Disposition: form-data; name="{k}"\r\n\r\n{v}\r\n'.encode() for k, v in (('profileId', profile), ('complianceId', cid))])
    body += f'--{bnd}\r\nContent-Disposition: form-data; name="file"; filename="{name}"\r\nContent-Type: application/octet-stream\r\n\r\n'.encode() + data + f'\r\n--{bnd}--\r\n'.encode()
    return sess.call('POST', '/api/compliance-tracker/documents', raw=body, headers={'Content-Type': f'multipart/form-data; boundary={bnd}'})
