step('it is listed with that compliance', len(d) == 1 and d[0]['name'] == 'T2 filed 2026.pdf' and d[0]['size'] == len(PDF), d)
r = urllib.request.Request(B + f'/api/compliance-tracker/documents?id={DOC}', headers={'Cookie': cli.cookie})
with cli.op.open(r) as resp: got = resp.read(); disp = resp.headers.get('Content-Disposition', '')
step('and comes back byte for byte', got == PDF and 'attachment' in disp, (len(got), disp))
